import{_ as a,o as n,c as t,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Panel and moderation","description":"","frontmatter":{"pageId":"admins/administration","contentRevision":1},"headers":[],"relativePath":"en/admins/administration.md","filePath":"en/admins/administration.md"}'),r={name:"en/admins/administration.md"};function s(o,e,l,d,c,p){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="panel-and-moderation" tabindex="-1">Panel and moderation <a class="header-anchor" href="#panel-and-moderation" aria-label="Permalink to &quot;Panel and moderation&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Open HTTPS /admin/ and sign in with legacy Admin:ApiToken. The panel exposes players, status, economy, raids and audit history. Use a separate API token for integrations rather than copying a cookie.</p><p>Start by reading player/status/actions and confirming IDs. Kick disconnects; mute restricts chat; ban denies login; economy freeze and raids freeze control separate subsystems. Record reasons in the audit.</p><p>Rollback selects a specific save version; reset creates a new colony timeline and clears related permissions. Archive retains a colony separately; restore-colony restores it subject to context checks. Coop rollback clears pawn assignments; revocation ends its session. Administrators may withdraw influence with an expected version, but cannot enable it for a player.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Reset, rollback, recreateworld and restore have destructive consequences: obtain confirmation and a verified backup first. Do not compensate a failure with wallet +n before inspecting escrow. Unfreezing does not repair a damaged save.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./cli">CLI reference</a></li><li><a href="./api">REST API reference</a></li><li><a href="./backup-recovery">Backup and recovery</a></li></ul>',10)])])}const u=a(r,[["render",s]]);export{h as __pageData,u as default};
